-- PASO 1: Cambiar campo estado a VARCHAR
ALTER TABLE notificaciones MODIFY COLUMN estado VARCHAR(50) DEFAULT 'Pendiente';

-- PASO 2: Normalizar resultados en visitas
UPDATE visitas SET resultado = 'Atiende' WHERE resultado = 'Entregado';
UPDATE visitas SET resultado = 'No Atiende' WHERE resultado LIKE '%No Atiende%';

-- PASO 3: Actualizar estado desde última visita
UPDATE notificaciones n
INNER JOIN (
    SELECT v1.notificacion_id, v1.resultado, v1.fecha
    FROM visitas v1
    INNER JOIN (
        SELECT notificacion_id, MAX(fecha) as max_fecha
        FROM visitas GROUP BY notificacion_id
    ) v2 ON v1.notificacion_id = v2.notificacion_id AND v1.fecha = v2.max_fecha
    WHERE v1.resultado IS NOT NULL AND v1.resultado != ''
) ultima ON n.id = ultima.notificacion_id
SET n.estado = ultima.resultado, n.fecha_diligencia = ultima.fecha
WHERE n.migrated_from_glide = 1;

UPDATE notificaciones SET estado = 'Pendiente' WHERE (estado IS NULL OR estado = '' OR estado = 'pendiente') AND migrated_from_glide = 1;

